async def act(page):
    # Use explore_page_and_links to discover all linked pages from the homepage
    result = await explore_page_and_links(page, start_url="/")

    # Search for a page with 'Archives' in title or URL
    archives_page = None
    for page_info in result:
        if 'archives' in page_info['title'].lower() or 'archives' in page_info['url'].lower():
            archives_page = page_info
            break

    if archives_page:
        # Navigate to the archives page
        await page.goto(archives_page['url'])

        # Now search for Archives section on this new page
        archives_section = page.get_by_role("heading", name="Archives", exact=False)
        if await archives_section.count() == 0:
            archives_section = page.get_by_text("Archives", exact=False)

        if await archives_section.count() > 0:
            # Find parent element using filter
            parent = page.get_by_role("region").filter(has=archives_section)
            if await parent.count() == 0:
                parent = page.get_by_role("group").filter(has=archives_section)
            if await parent.count() == 0:
                parent = page.get_by_role("complementary").filter(has=archives_section)
            if await parent.count() == 0:
                parent = page.get_by_role("navigation").filter(has=archives_section)

            # Find all links within this parent section
            links = parent.get_by_role("link")
            link_count = await links.count()
            if link_count >= 3:
                # Click the third link (index 2)
                third_link = links.nth(2)
                await third_link.click()
                return
            else:
                print("Not enough links in Archives section.")
        else:
            print("Archives section not found on the page.")
    else:
        print("No pages found containing 'Archives'.")

